// Worker pattern em Go (simplificado)
type FenceEvent struct {
  UserID   string
  FenceID  string
  Type     string  // "entry", "exit", "dwell"
  At       time.Time
  Lat, Lng float64
}

func processHeartbeat(ctx context.Context, hb Heartbeat) error {
  // 1. Quais fences contêm este ponto?
  fences, err := pgx.Query(ctx,
    `SELECT id FROM fences 
     WHERE geom && ST_SetSRID(ST_MakePoint($1, $2), 4326)
       AND ST_Contains(geom, ST_SetSRID(ST_MakePoint($1, $2), 4326))`,
    hb.Lng, hb.Lat)
  if err != nil { return err }
  defer fences.Close()

  insideNow := map[string]bool{}
  for fences.Next() {
    var fid string
    fences.Scan(&fid)
    insideNow[fid] = true
  }

  // 2. Compara com estado anterior em Redis
  prev, _ := redis.SMembers(ctx, "user:"+hb.UserID+":fences").Result()
  prevSet := setOf(prev)

  // 3. Diff = transições
  for fid := range insideNow {
    if !prevSet[fid] {
      emit(FenceEvent{hb.UserID, fid, "entry", time.Now(), hb.Lat, hb.Lng})
    }
  }
  for fid := range prevSet {
    if !insideNow[fid] {
      emit(FenceEvent{hb.UserID, fid, "exit", time.Now(), hb.Lat, hb.Lng})
    }
  }

  // 4. Atualiza estado
  redis.Del(ctx, "user:"+hb.UserID+":fences")
  if len(insideNow) > 0 {
    members := keysOf(insideNow)
    redis.SAdd(ctx, "user:"+hb.UserID+":fences", members...)
    redis.Expire(ctx, "user:"+hb.UserID+":fences", 5*time.Minute)
  }

  return nil
}

// Fluxo no checkout — cliente verifica se endereço é entregável
async function checkDeliverable(addressLat: number, addressLng: number) {
  // 1. Geofence: está em alguma zona de cobertura?
  const zonas = await fetch("/api/zonas/contains", {
    method: "POST",
    body: JSON.stringify({ lat: addressLat, lng: addressLng }),
  }).then(r => r.json());
  if (zonas.length === 0) return { ok: false, reason: "fora_cobertura" };

  // 2. Isócrona: tem restaurante a até 30min de bike?
  const isochrone = await fetch(
    `https://valhalla/isochrone?lat=${addressLat}&lng=${addressLng}&minutes=30&vehicle=bicycle`
  ).then(r => r.json());

  // 3. PostGIS: quais restaurantes caem dentro da isócrona?
  const restaurantes = await fetch("/api/restaurantes/within", {
    method: "POST",
    body: JSON.stringify({ geojson: isochrone }),
  }).then(r => r.json());

  return { ok: true, restaurantes };
}
